// Files outside the sandbox (document picker, iCloud Drive) need a bookmark
func remember(_ picked: URL) throws -> Data {
  guard picked.startAccessingSecurityScopedResource() else { throw PickError.denied }
  defer { picked.stopAccessingSecurityScopedResource() }
  return try picked.bookmarkData()   // .withSecurityScope is a macOS-only option
}

func resolve(_ bookmark: Data) throws -> (URL, Data?) {
  var isStale = false
  let url = try URL(resolvingBookmarkData: bookmark, bookmarkDataIsStale: &isStale)
  // stale means the file moved: store the fresh bookmark or the next launch fails
  return (url, isStale ? try? url.bookmarkData() : nil)
}

