@Model final class Article {
  @Attribute(.unique) var serverID: String
  var title: String
  var updatedAt: Date
  init(serverID: String, title: String, updatedAt: Date) {
    self.serverID = serverID; self.title = title; self.updatedAt = updatedAt
  }
}

