}
try context.save()   // a known serverID is updated in place, not duplicated

// Core Data: constraints in the model editor plus a policy, or the save throws
context.mergePolicy = NSMergeByPropertyObjectTrumpMergePolicy

// A CloudKit-synced store gets no constraints: dedupe by hand, in ONE fetch
let ids = payload.map(\.id)
let found = try context.fetch(
  FetchDescriptor<Article>(predicate: #Predicate { ids.contains($0.serverID) })
)
var existing = Dictionary(uniqueKeysWithValues: found.map { ($0.serverID, $0) })

for dto in payload {
  if let row = existing[dto.id] {
    guard dto.updatedAt > row.updatedAt else { continue }  // never clobber newer local data
    row.title = dto.title
    row.updatedAt = dto.updatedAt
  } else {
    let row = Article(serverID: dto.id, title: dto.title, updatedAt: dto.updatedAt)
    context.insert(row)
    existing[dto.id] = row                                 // a batch can repeat an id
  }
}
try context.save()

