// Do not attempt the work before the keys exist
func handle(_ task: BGProcessingTask) async {
  guard await UIApplication.shared.isProtectedDataAvailable else {
    task.setTaskCompleted(success: false)   // reschedule; nothing is readable yet
    return
  }
  await sync()
  await persistence.closeStore()            // 0xdead10cc if you stay open while suspended
  task.setTaskCompleted(success: true)
}

// Close before the keys are evicted, reopen when they come back
NotificationCenter.default.addObserver(
  forName: UIApplication.protectedDataWillBecomeUnavailableNotification,
  object: nil, queue: .main) { _ in Task { await persistence.closeStore() } }
NotificationCenter.default.addObserver(
  forName: UIApplication.protectedDataDidBecomeAvailableNotification,
  object: nil, queue: .main) { _ in Task { await persistence.openStore() } }

