viewContext.mergePolicy = NSErrorMergePolicy

do {
  try viewContext.save()
} catch let error as NSError where error.code == NSManagedObjectMergeError {
  let conflicts = error.userInfo["conflictList"] as? [NSMergeConflict] ?? []
  for conflict in conflicts {
    // conflict.objectSnapshot — what this context fetched
    // conflict.persistedSnapshot — what the store holds now
    presentConflict(conflict)   // a product decision, not a policy
  }
}

// Imports are different: property-level merge, incoming values win
backgroundContext.mergePolicy = NSMergeByPropertyObjectTrumpMergePolicy
// NSOverwriteMergePolicy would also push back fields this context never read

// An editing screen gets its own short-lived child context
